import json

# Signed predicates: "not_" denotes explicit negation, not absence.
facts = {
    ("not_build_power_plant_near", "finch", "mermaid"),
    ("card_color", "mermaid", "green"),
}
primary_colors = {"red", "green", "blue"}
proof = {}

# Evaluate the complete dependency slice for the queried predicate.
changed = True
while changed:
    changed = False
    additions = []

    # Primary-color predicate uses the specified RGB convention.
    for fact in sorted(facts):
        if fact[0] == "card_color" and fact[2] in primary_colors:
            additions.append((
                ("has_primary_color_card", fact[1]),
                {"definition": "RGB primary colors", "premises": [fact]}
            ))

    # Rule1: "close to" and "near" describe the same stated relation.
    premise = ("not_build_power_plant_near", "finch", "mermaid")
    if premise in facts:
        additions.append((
            ("shouts_at", "mermaid", "cougar"),
            {"rule": "Rule1", "premises": [premise]}
        ))

    # Rule3.
    premise = ("has_primary_color_card", "mermaid")
    if premise in facts:
        additions.append((
            ("not_acquire_photo", "mermaid", "fangtooth"),
            {"rule": "Rule3", "premises": [premise]}
        ))

    # Rule8 binds both antecedents and the conclusion to the same animal.
    animals = {f[1] for f in facts if len(f) > 1}
    for animal in sorted(animals):
        premises = [
            ("shouts_at", animal, "cougar"),
            ("not_acquire_photo", animal, "fangtooth"),
        ]
        if all(p in facts for p in premises):
            additions.append((
                ("stops_victory", animal, "zebra"),
                {"rule": "Rule8", "premises": premises}
            ))

    for conclusion, justification in additions:
        if conclusion not in facts:
            facts.add(conclusion)
            proof[conclusion] = justification
            changed = True

query = ("stops_victory", "mermaid", "zebra")
opposite = ("not_stops_victory", "mermaid", "zebra")

positive = query in facts
negative = opposite in facts
if positive and not negative:
    answer = "proved"
elif negative and not positive:
    answer = "disproved"
elif not positive and not negative:
    answer = "unknown"
else:
    print("UNSUPPORTED")
    raise SystemExit

evidence = []
visited = set()

def collect(fact):
    if fact in visited:
        return
    visited.add(fact)
    if fact in proof:
        justification = proof[fact]
        for premise in justification["premises"]:
            collect(premise)
        evidence.append({"fact": fact, **justification})
    else:
        evidence.append({"fact": fact, "source": "given"})

if positive:
    collect(query)
if negative:
    collect(opposite)

print(json.dumps(
    {"final_answer": answer, "evidence": evidence},
    separators=(",", ":")
))
